import { useEffect, useMemo, useState, type CSSProperties } from "react";
import { createRoot } from "react-dom/client";
import type { HubSnapshot, OrchestrationPlanRecord, Participant, RoomEvent, Task } from "@mireva/protocol";
import "./styles.css";
import "./sprites.css";
import "./monitor.css";
import "./runner-connect.css";
import "./office-sprites.css";
import "./workspace-pages.css";

const defaultHub = "https://mireva-hub.renatojosesfc.workers.dev";
const inviteParameters = new URLSearchParams(window.location.search);
const localProjectDirectory = import.meta.env.VITE_MIREVA_PROJECT_DIR ?? "";
const roomStorageKey = `mireva:room:${localProjectDirectory || window.location.pathname}`;
const initialHub = inviteParameters.get("hub") ?? localStorage.getItem("mireva:hub") ?? defaultHub;
const initialRoom = inviteParameters.get("room") ?? localStorage.getItem(roomStorageKey) ?? "";
const localAgentUrl = import.meta.env.VITE_MIREVA_AGENT_URL ?? "http://127.0.0.1:49321";
const localAgentToken = import.meta.env.VITE_MIREVA_AGENT_TOKEN ?? "";
const inviteBaseUrl = import.meta.env.VITE_MIREVA_INVITE_BASE_URL || window.location.origin;
type WorkspacePage = "office" | "orchestrator" | "tasks" | "team" | "settings";
const workspacePages: WorkspacePage[] = ["office", "orchestrator", "tasks", "team", "settings"];
const initialPage = workspacePages.includes(window.location.hash.slice(1) as WorkspacePage) ? window.location.hash.slice(1) as WorkspacePage : "office";
const roles = ["GENERAL", "ORCHESTRATOR", "DEVELOPMENT", "RESEARCH", "TEST", "REVIEW"] as const;
const roleInfo: Record<(typeof roles)[number], { label: string; icon: string; capabilities: string[] }> = {
  GENERAL: { label: "Geral", icon: "✦", capabilities: [] }, ORCHESTRATOR: { label: "Orquestrador", icon: "◎", capabilities: ["ORCHESTRATE"] }, DEVELOPMENT: { label: "Desenvolvimento", icon: "⌘", capabilities: ["CODE", "GIT"] }, RESEARCH: { label: "Pesquisa", icon: "⌕", capabilities: ["RESEARCH"] }, TEST: { label: "Testes", icon: "✓", capabilities: ["TEST"] }, REVIEW: { label: "Revisão", icon: "◇", capabilities: ["REVIEW", "GIT"] },
};
const stateInfo: Record<string, { label: string; color: string; icon: string }> = {
  AVAILABLE: { label: "Disponível", color: "#55b9ff", icon: "✦" }, WORKING: { label: "Trabalhando", color: "#52e09d", icon: "↟" }, RESEARCHING: { label: "Pesquisando", color: "#ffd85c", icon: "⌕" }, TESTING: { label: "Testando", color: "#b08cff", icon: "✓" }, WAITING_APPROVAL: { label: "Aguardando aprovação", color: "#ffab65", icon: "!" }, BLOCKED: { label: "Bloqueado", color: "#ff6876", icon: "×" }, DISCONNECTED: { label: "Desconectado", color: "#7d849b", icon: "○" },
};
const taskStates = ["BACKLOG", "READY", "CLAIMED", "RUNNING", "REVIEW", "DONE"];
const progressFor = (task?: Task) => !task ? 0 : ({ BACKLOG: 5, READY: 15, CLAIMED: 30, RUNNING: 58, REVIEW: 88, DONE: 100, FAILED: 100, BLOCKED: 38, CANCELLED: 100, WAITING_APPROVAL: 92 }[task.status] ?? 0);
const taskStateLabel = (status: string) => ({ BACKLOG: "Fila", READY: "Pronta", CLAIMED: "Assumida", RUNNING: "Em execução", REVIEW: "Em revisão", DONE: "Concluída" }[status] ?? status);
const spriteNames = ["renato", "codex", "copilot", "gemini", "qa"];
const pixelAvatarUrl = (seed: string) => `/sprites/${spriteNames[[...seed].reduce((total, char) => total + char.charCodeAt(0), 0) % spriteNames.length]}.svg`;
const usagePercent = (usage: Participant["usage"]) => usage ? Math.min(100, Math.round((usage.used / usage.limit) * 100)) : null;
const usageTone = (usage: Participant["usage"]) => { const percent = usagePercent(usage) ?? 0; return percent >= 90 ? "danger" : percent >= 70 ? "warning" : "safe"; };
const seenLabel = (value: string) => { const seconds = Math.max(0, Math.round((Date.now() - Date.parse(value)) / 1_000)); return seconds < 10 ? "agora" : seconds < 60 ? `há ${seconds}s` : seconds < 3_600 ? `há ${Math.floor(seconds / 60)} min` : `há ${Math.floor(seconds / 3_600)} h`; };

function App() {
  const [hub, setHub] = useState(initialHub);
  const [roomCode, setRoomCode] = useState(initialRoom);
  const [snapshot, setSnapshot] = useState<HubSnapshot | null>(null);
  const [events, setEvents] = useState<RoomEvent[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [page, setPage] = useState<WorkspacePage>(initialPage);
  const [showRunnerConnect, setShowRunnerConnect] = useState(false);
  const [showRoomSetup, setShowRoomSetup] = useState(!initialRoom);
  const [requestText, setRequestText] = useState("");
  const [error, setError] = useState("");
  const navigate = (nextPage: WorkspacePage) => { setPage(nextPage); window.location.hash = nextPage; window.scrollTo({ top: 0, behavior: "smooth" }); };
  const load = async () => {
    if (!roomCode) return;
    try {
      const [room, log] = await Promise.all([
        fetch(`${hub}/rooms/${roomCode}`).then(async (response) => { if (!response.ok) throw new Error("Sala não encontrada"); return response.json() as Promise<HubSnapshot>; }),
        fetch(`${hub}/rooms/${roomCode}/events?after=0`).then(async (response) => { if (!response.ok) throw new Error("Não foi possível carregar os eventos"); return response.json() as Promise<RoomEvent[]>; }),
      ]);
      const normalizedRoom = { ...room, plans: room.plans ?? [] };
      setSnapshot(normalizedRoom); setEvents(log); setSelectedId((current) => current && normalizedRoom.participants.some((participant) => participant.id === current) ? current : null); setError("");
      localStorage.setItem("mireva:hub", hub); localStorage.setItem(roomStorageKey, roomCode);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível carregar a sala"); }
  };
  const createRoom = async (name: string, ownerName: string) => {
    try {
      const response = await fetch(`${hub}/rooms`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ name, ownerName }) });
      const result = await response.json() as { room?: { code: string }; error?: string };
      if (!response.ok || !result.room) throw new Error(result.error ?? "Não foi possível criar o escritório");
      setRoomCode(result.room.code);
      setShowRoomSetup(false);
      navigate("office");
      localStorage.setItem("mireva:hub", hub);
      localStorage.setItem(roomStorageKey, result.room.code);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível criar o escritório"); }
  };
  const enterRoom = (input: string) => {
    const fromLink = new URLSearchParams(input.includes("?") ? input.slice(input.indexOf("?") + 1) : "").get("room");
    const code = (fromLink ?? input).replace(/[^a-z0-9]/gi, "").slice(-8).toUpperCase();
    if (code.length !== 8) { setError("Informe o código de 8 caracteres ou cole o convite da sala."); return; }
    setRoomCode(code); setShowRoomSetup(false); setError(""); navigate("office");
  };
  useEffect(() => { void load(); const timer = window.setInterval(() => void load(), 2_500); return () => window.clearInterval(timer); }, [hub, roomCode]);
  useEffect(() => { const syncPage = () => { const next = window.location.hash.slice(1) as WorkspacePage; if (workspacePages.includes(next)) setPage(next); }; window.addEventListener("hashchange", syncPage); return () => window.removeEventListener("hashchange", syncPage); }, []);
  const assigned = useMemo(() => new Map(snapshot?.tasks.filter((task) => task.assignedParticipantId).map((task) => [task.assignedParticipantId!, task])), [snapshot]);
  const selected = selectedId ? snapshot?.participants.find((person) => person.id === selectedId) : undefined;
  const selectedTask = selected ? assigned.get(selected.id) : undefined;
  const officeRunners = snapshot?.participants.filter((person) => person.agent !== "human" && person.role !== "ORCHESTRATOR") ?? [];
  const desks = Array.from({ length: 5 }, (_, index) => officeRunners[index] ?? null);
  const activeCount = snapshot?.participants.filter((person) => person.agent !== "human" && person.state !== "DISCONNECTED").length ?? 0;
  const decide = async (task: Task, status: "DONE" | "WAITING_APPROVAL") => {
    if (!snapshot) return;
    const result = status === "DONE" ? "Aprovada pelo responsável" : window.prompt("Qual ajuste o agente precisa fazer?");
    if (result === null) return;
    try { const response = await fetch(`${hub}/rooms/${roomCode}/tasks/${task.id}/decision`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ownerId: snapshot.room.ownerId, status, result }) }); if (!response.ok) throw new Error("Não foi possível registrar a decisão"); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível registrar a decisão"); }
  };
  const sendRequest = async () => {
    if (!snapshot || !requestText.trim()) return;
    try { const response = await fetch(`${hub}/rooms/${roomCode}/events`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ participantId: snapshot.room.ownerId, kind: "ORCHESTRATOR_REQUEST", payload: { message: requestText.trim() } }) }); if (!response.ok) throw new Error("Não foi possível enviar o pedido"); setRequestText(""); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível enviar o pedido"); }
  };
  const decidePlan = async (plan: OrchestrationPlanRecord, status: "APPROVED" | "REJECTED") => {
    if (!snapshot) return;
    try { const response = await fetch(`${hub}/rooms/${roomCode}/plans/${plan.id}/decision`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ownerId: snapshot.room.ownerId, status }) }); if (!response.ok) throw new Error("Não foi possível decidir o plano"); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível decidir o plano"); }
  };
  const dispatchTasks = async () => {
    if (!snapshot) return;
    try { const response = await fetch(`${hub}/rooms/${roomCode}/tasks/dispatch`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ownerId: snapshot.room.ownerId }) }); if (!response.ok) throw new Error("Não foi possível distribuir as tarefas"); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível distribuir as tarefas"); }
  };
  const updateProjectMemory = async (content: string) => {
    if (!snapshot) return;
    try { const response = await fetch(`${hub}/rooms/${roomCode}/memory`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ownerId: snapshot.room.ownerId, content }) }); if (!response.ok) throw new Error("Não foi possível salvar a memória do projeto"); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível salvar a memória do projeto"); }
  };
  const configureParticipant = async (participant: Participant, role: (typeof roles)[number], capabilities: string[]) => {
    if (!snapshot) return;
    try {
      const response = await fetch(`${hub}/rooms/${roomCode}/participants/${participant.id}/config`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ownerId: snapshot.room.ownerId, role, capabilities }) });
      if (!response.ok) throw new Error("Não foi possível atualizar a estação");
      await load();
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível atualizar a estação"); }
  };
  const reportUsage = async (participant: Participant, input: { used: number; limit: number; unit: string; resetAt: string | null }) => {
    if (!snapshot) return;
    try {
      const response = await fetch(`${hub}/rooms/${roomCode}/participants/${participant.id}/usage`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ reporterId: snapshot.room.ownerId, ...input }) });
      if (!response.ok) throw new Error("Não foi possível registrar o limite");
      await load();
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível registrar o limite"); }
  };
  return <main className="office-app">
    <header className="topbar"><div><p className="eyebrow">MIREVA WORKSPACE <span>•</span> LIVE OFFICE</p><h1>{snapshot?.room.name ?? "Seu escritório de IAs"}</h1><p className="subtitle">Acompanhe a equipe, as tarefas e as decisões em um só lugar.</p></div><div className="topbar-status"><span className={snapshot ? "live-dot" : "offline-dot"} />{snapshot ? "Sala sincronizada" : "Aguardando conexão"}</div></header>
    {snapshot && <WorkspaceNavigation page={page} roomCode={roomCode} onNavigate={navigate} onConnect={() => setShowRunnerConnect(true)} />}
    {error && <p className="error-message">{error}</p>}
    {showRoomSetup && <RoomSetup onCreate={createRoom} onEnter={enterRoom} onClose={roomCode ? () => setShowRoomSetup(false) : undefined} />}
    {showRunnerConnect && <RunnerConnectWizard roomCode={roomCode} hub={hub} onClose={() => setShowRunnerConnect(false)} />}
    {snapshot && <>
      {page === "office" && <><PageHeading eyebrow="VISÃO GERAL" title="Escritório" description="Veja a equipe trabalhando e abra qualquer estação para inspecionar." /><section className="stats" aria-label="Resumo do projeto"><Metric value={`${activeCount}/5`} label="agentes ativos" /><Metric value={snapshot.tasks.filter((task) => task.status === "RUNNING").length} label="em execução" /><Metric value={snapshot.tasks.filter((task) => task.status === "REVIEW").length} label="pedem decisão" /><Metric value={snapshot.tasks.filter((task) => task.status === "DONE").length} label="entregas feitas" /></section>
      <section className="workspace-layout"><div className="scene-card"><div className="scene-heading"><div><p className="eyebrow">ESCRITÓRIO VIRTUAL</p><h2>Equipe em tempo real</h2></div><span>{activeCount} agentes trabalhando agora</span></div><div className="office-scene pixel-office pixel-office-v2">
        <div className="office-wall"><div className="office-window window-a" /><div className="office-window window-b" /><img src="/sprites/office/Wall-Graph.png" className="wall-item graph-item" alt="" /><img src="/sprites/office/Wall-Clock.png" className="wall-item clock-item" alt="" /><img src="/sprites/office/Wall-Shelf.png" className="wall-item shelf-item" alt="" /><div className="project-display"><span>PROGRESSO DO PROJETO</span><strong>{snapshot.tasks.filter((task) => task.status === "DONE").length}<small> / {snapshot.tasks.length || 0}</small></strong><i><b style={{ width: `${snapshot.tasks.length ? Math.round((snapshot.tasks.filter((task) => task.status === "DONE").length / snapshot.tasks.length) * 100) : 0}%` }} /></i></div></div>
        <div className="office-floor" />
        <div className="room-label control-label">CENTRO DE CONTROLE</div><div className="room-label team-label">EQUIPE DE AGENTES</div><div className="room-label lounge-label">ÁREA DE PAUSA</div>
        <div className="control-room"><button className="orchestrator-station" onClick={() => { setSelectedId(null); navigate("orchestrator"); }} aria-label="Abrir chat do orquestrador"><img className="boss-desk-sprite" src="/sprites/office/Boss-Desk.png" alt="" /><img className="boss-chair-sprite" src="/sprites/office/Boss-Chair.png" alt="" /><img className="orchestrator-character" src="/sprites/characters/worker-right.gif" alt="" /><span className="orchestrator-status"><i /> ORQUESTRADOR</span><strong>Conversar e planejar</strong><small>Clique para abrir o chat</small></button><img className="control-bookshelf" src="/sprites/office/Tall-Bookshelf.png" alt="" /><img className="control-plant" src="/sprites/office/Big-Plant.png" alt="" /></div>
        <div className="team-room"><div className="desk-grid-v2">{desks.map((person, index) => <Desk key={person?.id ?? `slot-${index}`} person={person} task={person ? assigned.get(person.id) : undefined} index={index} selected={person?.id === selected?.id} onSelect={() => { if (person) setSelectedId(person.id); }} />)}</div></div>
        <div className="lounge-room" aria-hidden="true"><img className="lounge-sofa" src="/sprites/office/Big-Sofa.png" alt="" /><img className="lounge-table" src="/sprites/office/Big-Round-Table.png" alt="" /><img className="lounge-vending" src="/sprites/office/Vending-Machine.png" alt="" /><img className="lounge-coffee" src="/sprites/office/Coffee-Machine.png" alt="" /><img className="lounge-water" src="/sprites/office/Water-Dispenser.png" alt="" /><img className="lounge-plant" src="/sprites/office/Small-Plant.png" alt="" /></div>
        <div className="office-corridor"><span>↕ CIRCULAÇÃO</span></div>
      </div><div className="scene-footer"><span><i /> Atualização ao vivo</span><span>Clique em uma mesa para ver a atividade</span><span>{activeCount} de 5 estações conectadas</span></div></div>
        <aside className="agent-panel">{selected ? <><AgentDetails person={selected} task={selectedTask} events={events} onConfigure={configureParticipant} /><UsageDetails person={selected} onReport={reportUsage} /></> : <ControlCenterCard snapshot={snapshot} onOpen={() => navigate("orchestrator")} />}</aside></section></>}
      {page === "orchestrator" && <><PageHeading eyebrow="CENTRO DE CONTROLE" title="Orquestrador" description="Converse, aprove o plano e acompanhe as decisões em um espaço próprio." /><OrchestratorWorkspace snapshot={snapshot} events={events} onClose={() => navigate("office")} onDecision={decide} onPlanDecision={decidePlan} onDispatch={dispatchTasks} onMemoryUpdate={updateProjectMemory} requestText={requestText} onRequestText={setRequestText} onRequest={sendRequest} /></>}
      {page === "tasks" && <><PageHeading eyebrow="FLUXO DE TRABALHO" title="Tarefas" description="Acompanhe cada etapa do plano, das ideias às entregas aprovadas." /><section className="flow-section standalone-section"><div className="section-heading"><div><p className="eyebrow">QUADRO DO PROJETO</p><h2>Execução do plano</h2></div><span>{snapshot.tasks.length} tarefas no total</span></div><div className="task-flow">{taskStates.map((state) => <div className="flow-column" key={state}><h3>{taskStateLabel(state)} <small>{snapshot.tasks.filter((task) => task.status === state).length}</small></h3>{snapshot.tasks.filter((task) => task.status === state).map((task) => <TaskCard key={task.id} task={task} />)}{!snapshot.tasks.some((task) => task.status === state) && <p className="empty-state">Sem tarefas</p>}</div>)}</div></section><ActivityStream events={events} /></>}
      {page === "team" && <><PageHeading eyebrow="AGENTES CONECTADOS" title="Equipe" description="Veja disponibilidade, tarefas atuais, limites e saúde de cada runner." /><MonitoringPanel participants={snapshot.participants} assigned={assigned} /><TeamDirectory participants={snapshot.participants} assigned={assigned} onSelect={(participant) => { setSelectedId(participant.id); navigate("office"); }} onConnect={() => setShowRunnerConnect(true)} /></>}
      {page === "settings" && <><PageHeading eyebrow="PROJETO E CONEXÃO" title="Configurações" description="Gerencie a sala, o convite e o contexto compartilhado com as IAs." /><SettingsPage snapshot={snapshot} hub={hub} roomCode={roomCode} onConnect={() => setShowRunnerConnect(true)} onChangeRoom={() => setShowRoomSetup(true)} onMemoryUpdate={updateProjectMemory} /></>}
    </>}
  </main>;
}
function WorkspaceNavigation({ page, roomCode, onNavigate, onConnect }: { page: WorkspacePage; roomCode: string; onNavigate: (page: WorkspacePage) => void; onConnect: () => void }) {
  const items: Array<{ id: WorkspacePage; label: string; icon: string }> = [
    { id: "office", label: "Escritório", icon: "▦" },
    { id: "orchestrator", label: "Orquestrador", icon: "✦" },
    { id: "tasks", label: "Tarefas", icon: "✓" },
    { id: "team", label: "Equipe", icon: "●" },
    { id: "settings", label: "Configurações", icon: "⚙" },
  ];
  return <nav className="workspace-nav" aria-label="Navegação principal"><div className="workspace-nav-room"><span><i /> Sala ativa</span><strong>{roomCode}</strong></div><div className="workspace-nav-links">{items.map((item) => <button key={item.id} className={page === item.id ? "active" : ""} onClick={() => onNavigate(item.id)}><i>{item.icon}</i>{item.label}</button>)}</div><button className="nav-connect" onClick={onConnect}>+ Conectar IA</button></nav>;
}
function PageHeading({ eyebrow, title, description }: { eyebrow: string; title: string; description: string }) { return <header className="page-heading"><p className="eyebrow">{eyebrow}</p><h2>{title}</h2><p>{description}</p></header>; }
function Metric({ value, label }: { value: string | number; label: string }) { return <div className="metric"><strong>{value}</strong><span>{label}</span></div>; }
function RoomSetup({ onCreate, onEnter, onClose }: { onCreate: (name: string, ownerName: string) => void; onEnter: (value: string) => void; onClose?: () => void }) {
  const [mode, setMode] = useState<"create" | "enter">("create");
  const [name, setName] = useState("");
  const [ownerName, setOwnerName] = useState("");
  const [invite, setInvite] = useState("");
  return <div className="room-setup-backdrop"><section className="room-setup" aria-labelledby="room-setup-title"><div className="room-setup-art"><img src="/sprites/office/Boss-Desk.png" alt="" /><img src="/sprites/characters/worker-right.gif" alt="" /></div><div className="room-setup-copy"><p className="eyebrow">MIREVA WORKSPACE</p><h2 id="room-setup-title">Vamos abrir seu escritório</h2><p>Você não precisa configurar servidor, Hub ou arquivos internos. Escolha como quer começar.</p></div>{onClose && <button className="modal-close" onClick={onClose} aria-label="Fechar">×</button>}<div className="room-setup-tabs"><button className={mode === "create" ? "active" : ""} onClick={() => setMode("create")}>Criar escritório</button><button className={mode === "enter" ? "active" : ""} onClick={() => setMode("enter")}>Entrar em escritório</button></div>{mode === "create" ? <form className="room-setup-form" onSubmit={(event) => { event.preventDefault(); if (name.trim() && ownerName.trim()) onCreate(name.trim(), ownerName.trim()); }}><label>Nome do projeto<input value={name} onChange={(event) => setName(event.target.value)} placeholder="Ex.: Site do escritório Silva" autoFocus /></label><label>Seu nome<input value={ownerName} onChange={(event) => setOwnerName(event.target.value)} placeholder="Ex.: Renato" /></label><button disabled={!name.trim() || !ownerName.trim()}>Criar e abrir escritório <span>→</span></button><small>Depois você conecta o Codex, Copilot ou outra IA com alguns cliques.</small></form> : <form className="room-setup-form" onSubmit={(event) => { event.preventDefault(); onEnter(invite); }}><label>Código ou convite da sala<input value={invite} onChange={(event) => setInvite(event.target.value)} placeholder="Ex.: 4CB426DF ou cole o link" autoFocus /></label><button disabled={!invite.trim()}>Entrar no escritório <span>→</span></button><small>O código aparece no convite enviado por quem criou o projeto.</small></form>}<p className="room-setup-footnote">O Mireva cuida da conexão segura entre as máquinas. Você só escolhe o projeto e as IAs que vão trabalhar.</p></section></div>;
}

function RunnerConnectWizard({ roomCode, hub, onClose }: { roomCode: string; hub: string; onClose: () => void }) {
  const [name, setName] = useState("");
  const [agent, setAgent] = useState<"copilot" | "codex">("copilot");
  const [isOrchestrator, setIsOrchestrator] = useState(false);
  const role = isOrchestrator ? "ORCHESTRATOR" : "GENERAL";
  const capabilities = isOrchestrator ? "ORCHESTRATE" : "CODE,RESEARCH,TEST,GIT";
  const [copied, setCopied] = useState(false);
  const [projectDirectory, setProjectDirectory] = useState(localProjectDirectory);
  const [starting, setStarting] = useState(false);
  const [localMessage, setLocalMessage] = useState("");
  const quote = (value: string) => `"${value.replaceAll("\"", "\\\"")}"`;
  const command = `npx --yes @renatojose7/mireva@latest connect ${roomCode || "CODIGO_DA_SALA"} --hub ${quote(hub)} --name ${quote(name || "Nome do agente")} --agent ${agent} --role ${role} --capabilities ${quote(capabilities.replaceAll(" ", ""))}`;
  const inviteUrl = `${inviteBaseUrl}${window.location.pathname}?hub=${encodeURIComponent(hub)}&room=${encodeURIComponent(roomCode)}`;
  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=180x180&data=${encodeURIComponent(inviteUrl)}`;
  const copy = async () => { try { await navigator.clipboard.writeText(command); setCopied(true); window.setTimeout(() => setCopied(false), 2_500); } catch { setCopied(false); } };
  const startLocal = async () => { setStarting(true); setLocalMessage(""); try { const response = await fetch(`${localAgentUrl}/connect`, { method: "POST", headers: { "content-type": "application/json", "x-mireva-token": localAgentToken }, body: JSON.stringify({ roomCode, hub, name, agent, role, capabilities: capabilities.split(",").map((value) => value.trim()).filter(Boolean), projectDirectory }) }); const result = await response.json() as { error?: string }; if (!response.ok) throw new Error(result.error ?? "Não foi possível iniciar o runner"); setLocalMessage("Runner iniciado nesta máquina. A estação aparecerá em alguns segundos."); } catch (cause) { setLocalMessage(cause instanceof Error ? cause.message : "Mireva Agent local indisponível. Use o comando copiado."); } finally { setStarting(false); } };
  return <div className="runner-modal-backdrop" role="presentation" onMouseDown={onClose}><section className="runner-modal" role="dialog" aria-modal="true" aria-labelledby="runner-connect-title" onMouseDown={(event) => event.stopPropagation()}><button className="modal-close" onClick={onClose} aria-label="Fechar">×</button><p className="eyebrow">CONEXÃO GUIADA</p><h2 id="runner-connect-title">Conecte uma IA a esta sala</h2><p className="runner-modal-intro">Dê um nome à estação, escolha a IA e inicie. O Mireva cuida de entrar na sala e manter a conexão.</p>{!roomCode && <p className="wizard-warning">Abra uma sala antes de continuar.</p>}<div className="runner-form"><label>Nome da estação<input value={name} onChange={(event) => setName(event.target.value)} placeholder="Ex.: Copilot Frontend" autoFocus /></label><label>IA que vai trabalhar<select value={agent} onChange={(event) => setAgent(event.target.value as "copilot" | "codex")}><option value="copilot">GitHub Copilot</option><option value="codex">ChatGPT Codex</option></select></label>{!localProjectDirectory && <label className="project-folder">Pasta do projeto neste computador<input value={projectDirectory} onChange={(event) => setProjectDirectory(event.target.value)} placeholder="/home/voce/projetos/meu-site" /></label>}<label className="orchestrator-choice"><input type="checkbox" checked={isOrchestrator} onChange={(event) => setIsOrchestrator(event.target.checked)} /> Esta é a IA que vai organizar o projeto <small>Marque uma única estação como orquestrador. As demais executam as tarefas atribuídas.</small></label></div><button className="start-local-button" disabled={!roomCode || !name.trim() || !projectDirectory.trim() || starting} onClick={() => void startLocal()}>{starting ? "Conectando…" : isOrchestrator ? "Iniciar orquestrador" : "Iniciar IA"}</button>{localMessage && <p className="local-message">{localMessage}</p>}<div className="invite-box"><div><span>CONVIDAR OUTRA MÁQUINA</span><p>No outro computador, abra o Mireva dentro da pasta do projeto e use este convite para entrar nesta sala.</p><code>{inviteUrl}</code></div><img src={qrUrl} alt="QR code do convite da sala" /></div><details className="advanced-connect"><summary>Usar o terminal em vez da tela</summary><div className="generated-command"><code>{command}</code><button disabled={!roomCode || !name.trim()} onClick={() => void copy()}>{copied ? "Copiado ✓" : "Copiar comando"}</button></div></details><p className="runner-footnote">O Copilot ou Codex pedirá o login normal somente na primeira vez.</p></section></div>;
}
function Desk({ person, task, index, selected, onSelect }: { person: Participant | null; task?: Task; index: number; selected: boolean; onSelect: () => void }) {
  if (!person) return <div className={`desk-station-v2 desk-${index + 1} vacant`}><div className="workstation-art"><img className="desk-sprite-v2" src={index % 2 ? "/sprites/office/Desk-2.png" : "/sprites/office/Desk.png"} alt="" /><img className="chair-sprite-v2" src="/sprites/office/Chair.png" alt="" /><span className="vacant-plus-v2">+</span></div><div className="desk-label-v2"><small>ESTAÇÃO {String(index + 1).padStart(2, "0")}</small><strong>Livre</strong><span>Conectar agente</span></div></div>;
  const info = stateInfo[person.state] ?? stateInfo.DISCONNECTED;
  const role = roleInfo[person.role ?? "GENERAL"] ?? roleInfo.GENERAL;
  return <button className={`desk-station-v2 desk-${index + 1} ${selected ? "selected" : ""}`} style={{ "--accent": info.color, "--character-hue": `${index * 47}deg` } as CSSProperties} onClick={onSelect} aria-pressed={selected}><div className="workstation-art"><img className="desk-sprite-v2" src={index % 2 ? "/sprites/office/Desk-2.png" : "/sprites/office/Desk.png"} alt="" /><img className="chair-sprite-v2" src="/sprites/office/Chair.png" alt="" /><img className="worker-character" src={index % 2 ? "/sprites/characters/worker-left.gif" : "/sprites/characters/worker-right.gif"} alt="" aria-hidden="true" /><span className="presence-light-v2" /></div><div className="desk-label-v2"><small>ESTAÇÃO {String(index + 1).padStart(2, "0")}</small><strong>{person.name}</strong><span>{role.label} · {info.label}</span>{task && <em>{task.title}</em>}</div></button>;
}
function AgentDetails({ person, task, events, onConfigure }: { person: Participant; task?: Task; events: RoomEvent[]; onConfigure: (participant: Participant, role: (typeof roles)[number], capabilities: string[]) => void }) {
  const info = stateInfo[person.state] ?? stateInfo.DISCONNECTED;
  const [role, setRole] = useState<(typeof roles)[number]>(person.role ?? "GENERAL");
  const [capabilities, setCapabilities] = useState((person.capabilities ?? []).join(", "));
  useEffect(() => { setRole(person.role ?? "GENERAL"); setCapabilities((person.capabilities ?? []).join(", ")); }, [person]);
  const relevantEvents = events.filter((event) => event.participantId === person.id || (task && event.payload.taskId === task.id)).slice(-5).reverse();
  const deliveryEvent = relevantEvents.find((event) => typeof event.payload.delivery === "object" && event.payload.delivery !== null);
  const delivery = deliveryEvent?.payload.delivery as { branch?: string; files?: string[] } | undefined;
  const applyRole = () => onConfigure(person, role, capabilities.split(",").map((item) => item.trim().toUpperCase()).filter(Boolean));
  return <><div className="panel-heading"><p className="eyebrow">ESTAÇÃO SELECIONADA</p><img className="agent-mark sprite-profile" src={pixelAvatarUrl(person.name)} alt="" /><h2>{person.name}</h2><p>{person.agent} <b>·</b> {roleInfo[role].label}</p><span className="state-chip" style={{ "--accent": info.color } as CSSProperties}>{info.icon} {info.label}</span></div><div className="task-focus"><span>TAREFA ATUAL</span>{task ? <><h3>{task.title}</h3><p>{task.description || "Sem descrição adicional."}</p><div className="progress-track"><i style={{ width: `${progressFor(task)}%`, background: info.color }} /></div><small>{progressFor(task)}% · {taskStateLabel(task.status)}</small></> : <p>Este agente está livre para receber a próxima tarefa.</p>}</div><div className="detail-grid"><Detail label="Ferramenta" value={person.agent} /><Detail label="Função" value={roleInfo[role].label} /><Detail label="Branch" value={delivery?.branch ?? "Ainda não informado"} /><Detail label="Arquivos" value={delivery?.files?.length ? `${delivery.files.length} alterado(s)` : "Aguardando runner"} /></div>{person.agent !== "human" && <div className="station-config"><span>CONFIGURAR ESTAÇÃO</span><label>Função<select value={role} onChange={(event) => { const next = event.target.value as (typeof roles)[number]; setRole(next); setCapabilities(roleInfo[next].capabilities.join(", ")); }}>{roles.map((entry) => <option key={entry} value={entry}>{roleInfo[entry].label}</option>)}</select></label><label>Capacidades<input value={capabilities} onChange={(event) => setCapabilities(event.target.value)} placeholder="CODE, TEST" /></label><button onClick={applyRole}>Salvar função</button></div>}{delivery?.files?.length ? <div className="files-list"><span>ARQUIVOS OBSERVADOS</span>{delivery.files.slice(0, 4).map((file) => <code key={file}>{file}</code>)}</div> : null}<div className="panel-log"><div><h3>Eventos e atividade</h3><span>{relevantEvents.length}</span></div>{relevantEvents.length ? relevantEvents.map((event) => <p key={event.id}><i />{event.kind.replaceAll("_", " ")}<time>{new Date(event.createdAt).toLocaleTimeString("pt-BR")}</time></p>) : <p className="muted">Ainda não há eventos deste agente.</p>}</div></>;
}
function MonitoringPanel({ participants, assigned }: { participants: Participant[]; assigned: Map<string, Task> }) {
  const runners = participants.filter((participant) => participant.agent !== "human");
  const reported = runners.filter((participant) => participant.usage).length;
  return <section className="monitoring-section"><div className="section-heading"><div><p className="eyebrow">ACOMPANHAMENTO</p><h2>Saúde dos runners</h2></div><span>{reported}/{runners.length} limites informados</span></div><div className="runner-watch-list">{runners.map((person) => { const info = stateInfo[person.state] ?? stateInfo.DISCONNECTED; const usage = person.usage; const percent = usagePercent(usage); const task = assigned.get(person.id); return <article className="runner-watch" key={person.id}><header><img src={pixelAvatarUrl(person.name)} alt="" /><div><strong>{person.name}</strong><span>{person.agent} · visto {seenLabel(person.lastSeenAt)}</span></div><i style={{ background: info.color, boxShadow: `0 0 10px ${info.color}` }} /></header><p>{task?.title ?? (person.state === "DISCONNECTED" ? "Runner desconectado" : "Livre para receber tarefa")}</p>{usage && percent !== null ? <><div className={`limit-bar ${usageTone(usage)}`}><i style={{ width: `${percent}%` }} /></div><footer><b>{percent}%</b><span>{usage.used}/{usage.limit} {usage.unit}</span>{usage.resetAt && <em>reinicia {new Date(usage.resetAt).toLocaleDateString("pt-BR")}</em>}</footer></> : <footer className="limit-empty"><span>Limite ainda não informado</span></footer>}</article>; })}{!runners.length && <p className="empty-state">Conecte um runner para acompanhar sua atividade.</p>}</div></section>;
}

function TeamDirectory({ participants, assigned, onSelect, onConnect }: { participants: Participant[]; assigned: Map<string, Task>; onSelect: (participant: Participant) => void; onConnect: () => void }) {
  const agents = participants.filter((participant) => participant.agent !== "human");
  return <section className="team-directory"><div className="section-heading"><div><p className="eyebrow">DIRETÓRIO DA EQUIPE</p><h2>Estações e funções</h2></div><button onClick={onConnect}>+ Conectar IA</button></div><div className="team-directory-grid">{agents.map((person) => { const info = stateInfo[person.state] ?? stateInfo.DISCONNECTED; const task = assigned.get(person.id); return <button key={person.id} onClick={() => onSelect(person)} style={{ "--accent": info.color } as CSSProperties}><img src={pixelAvatarUrl(person.name)} alt="" /><div><strong>{person.name}</strong><span>{person.agent} · {roleInfo[person.role]?.label ?? "Geral"}</span><p>{task?.title ?? "Livre para receber tarefa"}</p></div><i /></button>; })}{!agents.length && <div className="team-empty"><strong>Nenhuma IA conectada</strong><p>Conecte o primeiro orquestrador ou runner para começar.</p><button onClick={onConnect}>Conectar primeira IA</button></div>}</div></section>;
}

function SettingsPage({ snapshot, hub, roomCode, onConnect, onChangeRoom, onMemoryUpdate }: { snapshot: HubSnapshot; hub: string; roomCode: string; onConnect: () => void; onChangeRoom: () => void; onMemoryUpdate: (content: string) => void }) {
  const [copied, setCopied] = useState(false);
  const inviteUrl = `${inviteBaseUrl}${window.location.pathname}?hub=${encodeURIComponent(hub)}&room=${encodeURIComponent(roomCode)}#office`;
  const copyInvite = async () => { try { await navigator.clipboard.writeText(inviteUrl); setCopied(true); window.setTimeout(() => setCopied(false), 2_500); } catch { setCopied(false); } };
  return <div className="settings-grid"><section className="settings-card"><p className="eyebrow">SALA ATUAL</p><h3>{snapshot.room.name}</h3><div className="settings-code"><span>Código da sala</span><strong>{roomCode}</strong></div><p>Compartilhe o convite com quem vai conectar outra máquina ao projeto.</p><div className="settings-actions"><button onClick={() => void copyInvite()}>{copied ? "Convite copiado ✓" : "Copiar convite"}</button><button className="secondary" onClick={onChangeRoom}>Trocar de sala</button></div></section><section className="settings-card"><p className="eyebrow">IA NESTA MÁQUINA</p><h3>Conectar uma estação</h3><p>O Mireva usa a pasta em que foi aberto. Escolha Codex ou Copilot e deixe a conexão rodando.</p><button onClick={onConnect}>Conectar IA</button><small>{import.meta.env.VITE_MIREVA_PROJECT_DIR || "Pasta do projeto detectada pelo launcher"}</small></section><section className="settings-card settings-memory"><p className="eyebrow">CONTEXTO COMPARTILHADO</p><h3>Regras do projeto</h3><ProjectMemory content={snapshot.projectMemory ?? ""} onSave={onMemoryUpdate} /></section></div>;
}

function UsageDetails({ person, onReport }: { person: Participant; onReport: (participant: Participant, input: { used: number; limit: number; unit: string; resetAt: string | null }) => void }) {
  const [used, setUsed] = useState(String(person.usage?.used ?? ""));
  const [limit, setLimit] = useState(String(person.usage?.limit ?? ""));
  const [unit, setUnit] = useState(person.usage?.unit ?? "créditos");
  const [resetAt, setResetAt] = useState(person.usage?.resetAt ? person.usage.resetAt.slice(0, 16) : "");
  useEffect(() => { setUsed(String(person.usage?.used ?? "")); setLimit(String(person.usage?.limit ?? "")); setUnit(person.usage?.unit ?? "créditos"); setResetAt(person.usage?.resetAt ? person.usage.resetAt.slice(0, 16) : ""); }, [person]);
  if (person.agent === "human") return null;
  const save = () => { const nextUsed = Number(used); const nextLimit = Number(limit); if (!Number.isFinite(nextUsed) || !Number.isFinite(nextLimit) || nextUsed < 0 || nextLimit <= 0) return; onReport(person, { used: nextUsed, limit: nextLimit, unit: unit.trim() || "créditos", resetAt: resetAt ? new Date(resetAt).toISOString() : null }); };
  const percent = usagePercent(person.usage);
  return <div className="usage-config"><div><span>LIMITE DO PROVEDOR</span>{percent !== null ? <b>{percent}% informado</b> : <b>Configure quando souber seu saldo</b>}</div><p>Registro manual: cada provedor mostra créditos e janelas de uso de um jeito diferente.</p><div className="usage-fields"><label>Usado<input type="number" min="0" value={used} onChange={(event) => setUsed(event.target.value)} placeholder="0" /></label><label>Limite<input type="number" min="1" value={limit} onChange={(event) => setLimit(event.target.value)} placeholder="100" /></label><label>Unidade<input value={unit} onChange={(event) => setUnit(event.target.value)} placeholder="créditos" /></label><label>Reinicia em<input type="datetime-local" value={resetAt} onChange={(event) => setResetAt(event.target.value)} /></label></div><button disabled={!limit || Number(limit) <= 0} onClick={save}>Atualizar acompanhamento</button></div>;
}

function ProjectMemory({ content, onSave }: { content: string; onSave: (content: string) => void }) { const [draft, setDraft] = useState(content); useEffect(() => setDraft(content), [content]); return <div className="project-memory"><span>MEMÓRIA DO PROJETO</span><p>Decisões, regras e contexto que o orquestrador e os runners recebem automaticamente.</p><textarea value={draft} onChange={(event) => setDraft(event.target.value)} placeholder="Ex.: usar React, manter o visual sóbrio, não alterar a página inicial..." /><button disabled={draft === content} onClick={() => onSave(draft)}>Salvar memória</button></div>; }
function ControlCenterCard({ snapshot, onOpen }: { snapshot: HubSnapshot; onOpen: () => void }) {
  const orchestrator = snapshot.participants.find((participant) => participant.role === "ORCHESTRATOR");
  return <div className="control-center-card"><div className="panel-heading"><p className="eyebrow">CENTRO DE CONTROLE</p><span className="agent-mark orchestrator-mark">MI</span><h2>Orquestrador</h2><p>{orchestrator ? `${orchestrator.name} está conectado à sala.` : "Conecte uma IA para organizar o projeto."}</p></div><div className="control-center-status"><span>CONVERSA E PLANEJAMENTO</span><strong>{snapshot.plans.some((plan) => plan.status === "DRAFT") ? "Há um plano aguardando sua decisão" : "Pronto para receber seu pedido"}</strong><p>Use uma conversa dedicada para explicar o que você quer construir, revisar o plano e distribuir as tarefas.</p></div><button onClick={onOpen}>Abrir conversa com o orquestrador <span>↗</span></button></div>;
}
function OrchestratorWorkspace({ snapshot, events, onClose, onDecision, onPlanDecision, onDispatch, onMemoryUpdate, requestText, onRequestText, onRequest }: { snapshot: HubSnapshot; events: RoomEvent[]; onClose: () => void; onDecision: (task: Task, status: "DONE" | "WAITING_APPROVAL") => void; onPlanDecision: (plan: OrchestrationPlanRecord, status: "APPROVED" | "REJECTED") => void; onDispatch: () => void; onMemoryUpdate: (content: string) => void; requestText: string; onRequestText: (value: string) => void; onRequest: () => void }) {
  const conversation = events.filter((event) => ["ORCHESTRATOR_REQUEST", "ORCHESTRATOR_RESPONSE", "PLAN_CREATED"].includes(event.kind)).slice(-30);
  const draftPlan = snapshot.plans.find((plan) => plan.status === "DRAFT");
  const reviewTasks = snapshot.tasks.filter((task) => task.status === "REVIEW");
  const readyTasks = snapshot.tasks.filter((task) => task.status === "READY");
  const orchestrator = snapshot.participants.find((participant) => participant.role === "ORCHESTRATOR");
  return <section className="orchestrator-workspace" aria-labelledby="orchestrator-title"><header><div><p className="eyebrow">MIREVA <span>•</span> CENTRO DE CONTROLE</p><h2 id="orchestrator-title">Conversa com o orquestrador</h2><p>{snapshot.room.name} · {orchestrator?.name ?? "Aguardando orquestrador"}</p></div><button onClick={onClose}>← Voltar ao escritório</button></header><div className="orchestrator-layout"><aside><div className="orchestrator-profile"><span className="agent-mark orchestrator-mark">MI</span><div><strong>Orquestrador</strong><small>{orchestrator ? `${orchestrator.agent} · ${stateInfo[orchestrator.state]?.label ?? orchestrator.state}` : "Nenhuma IA conectada"}</small></div></div><p className="orchestrator-sidebar-copy">Explique o resultado desejado. A IA propõe um plano; você aprova antes de qualquer runner executar.</p><details className="project-context"><summary>Contexto e regras do projeto</summary><ProjectMemory content={snapshot.projectMemory ?? ""} onSave={onMemoryUpdate} /></details><div className="orchestrator-side-stats"><span><b>{snapshot.participants.filter((person) => person.agent !== "human").length}</b> IAs na sala</span><span><b>{snapshot.tasks.length}</b> tarefas</span></div></aside><main className="orchestrator-chat-room"><div className="chat-room-history">{conversation.length ? conversation.map((event) => <article key={event.id} className={event.kind === "ORCHESTRATOR_REQUEST" ? "chat-owner" : "chat-orchestrator"}><span>{event.kind === "ORCHESTRATOR_REQUEST" ? "Você" : "Orquestrador"}</span><p>{event.kind === "ORCHESTRATOR_REQUEST" ? String(event.payload.message ?? "Pedido enviado") : String((event.payload.orchestrator as { summary?: string } | undefined)?.summary ?? event.payload.message ?? "Plano atualizado")}</p></article>) : <div className="chat-empty"><span className="agent-mark orchestrator-mark">MI</span><h3>O que vamos construir?</h3><p>Descreva o objetivo do projeto com suas próprias palavras. O orquestrador vai transformar isso em um plano claro para sua aprovação.</p></div>}{draftPlan && <div className="chat-plan"><span>PLANO PROPOSTO · {draftPlan.tasks.length} TAREFAS</span><strong>{draftPlan.summary}</strong><ol>{draftPlan.tasks.map((task, index) => <li key={`${task.title}-${index}`}>{task.title}</li>)}</ol><div><button onClick={() => onPlanDecision(draftPlan, "APPROVED")}>Aprovar plano</button><button onClick={() => onPlanDecision(draftPlan, "REJECTED")}>Recusar</button></div></div>}{readyTasks.length ? <button className="chat-dispatch" onClick={onDispatch}>Distribuir {readyTasks.length} tarefa(s) aprovada(s)</button> : null}{reviewTasks.map((task) => <div className="chat-review" key={task.id}><strong>{task.title}</strong><p>{task.result ?? "Entrega aguardando sua revisão."}</p><button onClick={() => onDecision(task, "DONE")}>Aprovar</button><button onClick={() => onDecision(task, "WAITING_APPROVAL")}>Pedir ajuste</button></div>)}</div><div className="chat-composer"><textarea autoFocus value={requestText} onChange={(event) => onRequestText(event.target.value)} placeholder="Ex.: Crie uma landing page para um escritório de advocacia, com visual sóbrio e formulário de contato." onKeyDown={(event) => { if (event.key === "Enter" && (event.ctrlKey || event.metaKey) && requestText.trim()) onRequest(); }} /><div><small>Ctrl + Enter para enviar</small><button disabled={!requestText.trim()} onClick={onRequest}>Enviar <span>↗</span></button></div></div></main></div></section>;
}
function OrchestratorDetails({ snapshot, events, onDecision, onPlanDecision, onDispatch, onMemoryUpdate, requestText, onRequestText, onRequest }: { snapshot: HubSnapshot; events: RoomEvent[]; onDecision: (task: Task, status: "DONE" | "WAITING_APPROVAL") => void; onPlanDecision: (plan: OrchestrationPlanRecord, status: "APPROVED" | "REJECTED") => void; onDispatch: () => void; onMemoryUpdate: (content: string) => void; requestText: string; onRequestText: (value: string) => void; onRequest: () => void }) { const reviewTasks = snapshot.tasks.filter((task) => task.status === "REVIEW"); const draftPlan = snapshot.plans.find((plan) => plan.status === "DRAFT"); const readyTasks = snapshot.tasks.filter((task) => task.status === "READY"); const conversation = events.filter((event) => ["ORCHESTRATOR_REQUEST", "ORCHESTRATOR_RESPONSE", "PLAN_CREATED"].includes(event.kind)).slice(-5); const agentCount = snapshot.participants.filter((participant) => participant.agent !== "human").length; return <><div className="panel-heading"><p className="eyebrow">CENTRO DE CONTROLE</p><span className="agent-mark orchestrator-mark">MI</span><h2>Chat do orquestrador</h2><p>Descreva o que você quer construir.</p><span className="state-chip neutral">✦ Monitorando o projeto</span></div><div className="orchestrator-chat"><span>CONVERSA DO PROJETO</span><div className="conversation">{conversation.length ? conversation.map((event) => <p className={event.kind === "ORCHESTRATOR_REQUEST" ? "from-owner" : "from-orchestrator"} key={event.id}>{event.kind === "ORCHESTRATOR_REQUEST" ? String(event.payload.message ?? "Pedido enviado") : String((event.payload.orchestrator as { summary?: string } | undefined)?.summary ?? event.payload.message ?? "Plano criado")}</p>) : <p className="chat-hint">Conte o resultado que você deseja. O orquestrador transformará o pedido em um plano para sua aprovação.</p>}</div><textarea value={requestText} onChange={(event) => onRequestText(event.target.value)} placeholder="Ex.: Crie uma landing page para um escritório de advocacia..." /><button disabled={!requestText.trim()} onClick={onRequest}>Enviar ao orquestrador <span>↗</span></button></div><details className="project-context"><summary>Contexto e regras do projeto</summary><ProjectMemory content={snapshot.projectMemory ?? ""} onSave={onMemoryUpdate} /></details>{draftPlan ? <div className="plan-card"><span>PLANO PROPOSTO · {draftPlan.tasks.length} TAREFAS</span><strong>{draftPlan.summary}</strong><ol>{draftPlan.tasks.map((task, index) => <li key={`${task.title}-${index}`}>{task.title}{task.dependencies.length ? <small> depende de {task.dependencies.map((dependency) => dependency + 1).join(", ")}</small> : null}</li>)}</ol><div><button onClick={() => onPlanDecision(draftPlan, "APPROVED")}>Aprovar plano</button><button onClick={() => onPlanDecision(draftPlan, "REJECTED")}>Recusar</button></div></div> : null}{readyTasks.length ? <button className="dispatch-button" onClick={onDispatch}>Distribuir {readyTasks.length} tarefa(s) pronta(s)</button> : null}<div className="task-focus"><span>PRÓXIMA DECISÃO</span><h3>{reviewTasks[0]?.title ?? "Nada aguardando aprovação"}</h3><p>{reviewTasks.length ? "Uma entrega está pronta para sua decisão." : "O fluxo está livre para continuar."}</p></div>{reviewTasks.map((task) => <div className="decision-card" key={task.id}><strong>{task.title}</strong><p>{task.result ?? "Entrega aguardando sua revisão."}</p><div><button onClick={() => onDecision(task, "DONE")}>Aprovar</button><button onClick={() => onDecision(task, "WAITING_APPROVAL")}>Pedir ajuste</button></div></div>)}<div className="detail-grid"><Detail label="Tarefas prontas" value={readyTasks.length} /><Detail label="Em revisão" value={reviewTasks.length} /><Detail label="Agentes" value={`${agentCount}/5`} /><Detail label="Eventos" value={snapshot.lastSequence} /></div></>;
}
function Detail({ label, value }: { label: string; value: string | number }) { return <div><span>{label}</span><strong>{value}</strong></div>; }
function TaskCard({ task }: { task: Task }) { return <article className="task-card"><span>P{task.priority}</span><h4>{task.title}</h4>{task.description && <p>{task.description}</p>}<footer>{task.assignedParticipantId ? "Com agente" : "Sem agente"}<b>{task.dependencies.length ? `${task.dependencies.length} dep.` : "Livre"}</b></footer></article>; }
function ActivityStream({ events }: { events: RoomEvent[] }) { const items = events.slice(-10).reverse(); const deliveries = events.filter((event) => typeof event.payload.delivery === "object").length; return <section className="activity-section"><div className="section-heading"><div><p className="eyebrow">ATIVIDADE AO VIVO</p><h2>O que a equipe está fazendo</h2></div><span>{deliveries} entrega(s) registradas · uso de créditos depende do provedor</span></div><div className="activity-list">{items.map((event) => <article key={event.id}><i className={`event-${event.kind.toLowerCase()}`} /><div><strong>{event.kind.replaceAll("_", " ")}</strong><p>{String((event.payload.event as { message?: string } | undefined)?.message ?? (event.payload.orchestrator as { summary?: string } | undefined)?.summary ?? (event.payload.task as { title?: string } | undefined)?.title ?? "Atualização registrada na sala")}</p></div><time>{new Date(event.createdAt).toLocaleTimeString("pt-BR")}</time></article>)}{!items.length && <p className="empty-state">Aguardando atividade na sala.</p>}</div></section>; }

createRoot(document.getElementById("root")!).render(<App />);
